<script setup>
import AppShell from '@/Components/AppShell.vue';import DataTableFooter from '@/Components/DataTableFooter.vue';import FileDropInput from '@/Components/FileDropInput.vue';import SortButton from '@/Components/SortButton.vue';import{useForm,Link,router}from'@inertiajs/vue3';import{ref,computed,reactive}from'vue';
const p=defineProps({requirements:Object,submissions:Object,tableFilters:Object});const type=ref('VISITOR');const form=useForm({type:'VISITOR',vendor_name:'',applicant_name:'',phone:'',description:'',documents:{}});const table=reactive({search:'',history_type:'',status:'',sort:'submitted_at',direction:'desc',per_page:10,...p.tableFilters});const docs=computed(()=>p.requirements[type.value].documents);const missing=computed(()=>docs.value.filter(x=>x.required&&!form.documents[x.code]).length);const selectType=x=>{type.value=x;form.type=x;form.documents={}};const setFile=(code,file)=>{form.documents={...form.documents,[code]:file};if(!file)delete form.documents[code]};const send=()=>form.post('/vendor/submissions',{forceFormData:true,onSuccess:()=>form.reset('vendor_name','applicant_name','phone','description','documents')});const load=()=>router.get('/vendor',table,{preserveState:true,preserveScroll:true,replace:true});const sort=c=>{table.direction=table.sort===c&&table.direction==='asc'?'desc':'asc';table.sort=c;load()};const size=v=>{table.per_page=v;load()};const detail=id=>'/vendor/submissions/'+id;const date=v=>new Date(v).toLocaleDateString('id-ID');
</script>
<template><AppShell title="Pengajuan Dokumen Vendor" subtitle="Lengkapi data dan unggah persyaratan PDF." eyebrow="Akun Vendor"><template #hero-title>Pengajuan Dokumen Vendor</template><template #hero-copy>Pilih jenis pengajuan, lengkapi data, lalu unggah dokumen PDF.</template>
<div class="lg:grid lg:grid-cols-[240px_minmax(0,1fr)] lg:items-start lg:gap-5">
<aside class="panel sticky top-5 hidden p-3 lg:block"><p class="px-3 pb-2 pt-1 text-[10px] font-black uppercase tracking-[.18em] text-slate-400">Jenis Pengajuan</p><button v-for="(value,key) in requirements" :key="key" type="button" class="vendor-type-link" :class="{'vendor-type-active':type===key}" @click="selectType(key)"><span class="vendor-type-icon">{{key==='VISITOR'?'♟':key==='WASKAT'?'◆':key==='IJIN_LINTAS'?'▰':'▤'}}</span><span class="text-left">{{value.label}}</span><span class="ml-auto">›</span></button><div class="mx-2 mt-4 rounded-xl bg-red-50 p-3"><p class="text-[10px] font-black text-red-700">FORMAT DOKUMEN</p><p class="mt-1 text-[11px] leading-5 text-red-700/70">PDF saja<br/>Maks. 3 MB per file<br/>Maks. 18 MB total</p></div></aside>
<div class="min-w-0"><label class="mb-4 block lg:hidden"><span class="mb-2 block text-xs font-black uppercase text-slate-500">Jenis Pengajuan</span><select :value="type" class="control" @change="selectType($event.target.value)"><option v-for="(value,key) in requirements" :key="key" :value="key">{{value.label}}</option></select></label>
<form class="panel" @submit.prevent="send"><div class="flex items-start justify-between gap-4 border-b border-slate-100 pb-5"><div><p class="text-[10px] font-black uppercase tracking-[.18em] text-red-600">Form Pengajuan</p><h2 class="mt-1 text-xl font-black">{{requirements[type].label}}</h2></div><span class="rounded-xl bg-red-50 px-3 py-2 text-[10px] font-black text-red-700">PDF · MAKS. 3 MB</span></div><div class="mt-5 grid gap-4 md:grid-cols-2"><label>Nama Vendor/Perusahaan *<input v-model="form.vendor_name" class="field" placeholder="Masukkan nama perusahaan"/><p class="err">{{form.errors.vendor_name}}</p></label><label>Nama Pemohon/PIC *<input v-model="form.applicant_name" class="field" placeholder="Masukkan nama lengkap"/><p class="err">{{form.errors.applicant_name}}</p></label><label>Nomor HP *<input v-model="form.phone" class="field" placeholder="Contoh: 081234567890"/><p class="err">{{form.errors.phone}}</p></label><label>Keterangan<textarea v-model="form.description" class="field" rows="1" placeholder="Keterangan tambahan (opsional)"/></label></div>
<div class="mt-7"><div class="mb-4"><h3 class="font-black">Dokumen Persyaratan</h3><p class="mt-1 text-xs text-slate-500">Klik area upload seperti input teks, drag & drop, atau paste dokumen dari clipboard.</p></div><div class="grid gap-5 xl:grid-cols-2"><FileDropInput v-for="document in docs" :key="document.code" :label="document.name" :required="document.required" :model-value="form.documents[document.code]" :error="form.errors['documents.'+document.code]" @update:model-value="setFile(document.code,$event)"/></div></div><p v-if="form.errors.documents" class="err mt-4">{{form.errors.documents}}</p><button :disabled="missing||form.processing" class="btn mt-7 w-full">{{missing?'LENGKAPI '+missing+' DOKUMEN WAJIB':(form.processing?'MENGIRIM...':'KIRIM PENGAJUAN')}}</button></form>
<section class="panel mt-6 overflow-hidden p-0"><div class="border-b px-5 py-4"><h2 class="panel-title">Riwayat Pengajuan</h2><p class="panel-copy">DataTable server-side · hanya pengajuan milik akun ini</p><form class="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4" @submit.prevent="load"><input v-model="table.search" class="control" placeholder="Cari ID, vendor, pemohon..."/><select v-model="table.history_type" class="control"><option value="">Semua jenis</option><option v-for="(value,key) in requirements" :value="key">{{value.label}}</option></select><select v-model="table.status" class="control"><option value="">Semua status</option><option v-for="x in ['SUBMITTED','APPROVED','REVISION','REJECTED','RELEASED']">{{x}}</option></select><button class="btn">Cari Data</button></form></div><div class="overflow-x-auto"><table class="data-table min-w-[900px]"><thead><tr><th>No</th><th><SortButton label="Tanggal" column="submitted_at" :sort="table.sort" :direction="table.direction" @sort="sort"/></th><th><SortButton label="ID Pengajuan" column="submission_number" :sort="table.sort" :direction="table.direction" @sort="sort"/></th><th><SortButton label="Jenis" column="type" :sort="table.sort" :direction="table.direction" @sort="sort"/></th><th><SortButton label="Vendor/Pemohon" column="vendor_name" :sort="table.sort" :direction="table.direction" @sort="sort"/></th><th><SortButton label="Status" column="status" :sort="table.sort" :direction="table.direction" @sort="sort"/></th><th>Dokumen</th><th>Aksi</th></tr></thead><tbody><tr v-for="(x,i) in submissions.data" :key="x.id"><td>{{submissions.from+i}}</td><td>{{date(x.submitted_at)}}</td><td><strong>{{x.submission_number}}</strong></td><td>{{x.type}}</td><td><strong>{{x.vendor_name}}</strong><small>{{x.applicant_name}}</small></td><td><span class="status-badge" :class="'status-'+x.status.toLowerCase()">{{x.status}}</span></td><td>{{x.documents_count}} file</td><td><Link :href="detail(x.id)" class="font-bold text-red-600">Detail</Link></td></tr></tbody></table><div v-if="!submissions.data.length" class="p-14 text-center text-sm text-slate-500">Riwayat pengajuan tidak ditemukan.</div></div><DataTableFooter :paginator="submissions" :per-page="table.per_page" @update:per-page="size"/></section>
</div></div></AppShell></template>
